import{_ as i,D as s,o as r,c as p,m as t,a as c,G as a,S as h}from"./chunks/framework.DuIEtbrD.js";const _=JSON.parse('{"title":"whistle抓包工具及调试技巧","description":"whistle更注重灵活性和可扩展性，适合前端开发者以及对工具可定制化要求较高的场景。其插件体系和规则配置是亮点","frontmatter":{"title":"whistle抓包工具及调试技巧","description":"whistle更注重灵活性和可扩展性，适合前端开发者以及对工具可定制化要求较高的场景。其插件体系和规则配置是亮点","keywords":"whistle,whistle抓包工具,手机抓包,ios抓包,android抓包,客户端抓包,抓包工具,Mac抓包,前端调试,frontend debugger,chrome调试,调试技能,node调试,线上调试","logo":"https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/icon-debug.png"},"headers":[],"relativePath":"frontend/debug-skill/whistle.md","filePath":"frontend/debug-skill/whistle.md","lastUpdated":1776945570000}'),d={name:"frontend/debug-skill/whistle.md"};function u(g,e,m,b,w,f){const n=s("Obsolete"),o=s("Reward"),l=s("Gitalk");return r(),p("div",null,[e[0]||(e[0]=t("h1",{id:"whistle抓包工具及调试技巧",tabindex:"-1"},[c("whistle抓包工具及调试技巧 "),t("a",{class:"header-anchor",href:"#whistle抓包工具及调试技巧","aria-label":'Permalink to "whistle抓包工具及调试技巧"'},"​")],-1)),a(n,{date:"2020-11-05"}),e[1]||(e[1]=h(`<p>往期文章我们已经讲过<a href="https://blog.usword.cn/frontend/debug-skill/fiddler.html" target="_blank" rel="noreferrer">fiddler</a>、<a href="https://blog.usword.cn/frontend/debug-skill/charles.html" target="_blank" rel="noreferrer">charles</a>以及<a href="https://blog.usword.cn/frontend/debug-skill/wireshark.html" target="_blank" rel="noreferrer">wireshark</a>等多种抓包工具，已经在工作中足够解决各种抓包问题了，但我今天还想再分享给大家一款抓包工具 <a href="https://github.com/avwo/whistle" target="_blank" rel="noreferrer">whistle</a>，因为它真的很优秀，本人在工作中也一直在用这个</p><p>为什么我会选择whistle，首先是fiddler不支持MacOS，其次Charles在M1芯片上会感觉明显的卡顿；除此之外是whistle更加轻量简单、开源免费！且满足前面几款抓包工具的所有功能，久而久之就一直在用这个了</p><p>whistle 是基于 Node.js 开发的跨平台抓包调试工具。支持 HTTP、HTTPS 请求的抓包分析，并具有插件化、灵活配置的特点。Whistle 通过代理的方式拦截请求，开发者可以方便地重定向、修改请求/响应内容，或进行接口 Mock 等操作</p><h2 id="下载安装" tabindex="-1">下载安装 <a class="header-anchor" href="#下载安装" aria-label="Permalink to &quot;下载安装&quot;">​</a></h2><p>由于whistle是基于NodeJS开发的，因此使用它有2种方式（推荐使用客户端）：</p><ul><li>安装NodeJS包，在终端使用命令行运行</li></ul><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#FFCB6B;">npm</span><span style="color:#C3E88D;"> install -g whistle</span></span>
<span class="line"></span>
<span class="line"><span style="color:#FFCB6B;">w2</span><span style="color:#C3E88D;"> start</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><blockquote><p>更多运行命令脚本，点这里查看 <a href="https://wproxy.org/whistle/install.html" target="_blank" rel="noreferrer">whistle命令文档</a></p></blockquote><ul><li>下载<a href="https://github.com/avwo/whistle/tags" target="_blank" rel="noreferrer">whistle客户端</a></li></ul><p>安装后界面大概如下</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_14.43.34.png" alt=""></p><h2 id="面板介绍" tabindex="-1">面板介绍 <a class="header-anchor" href="#面板介绍" aria-label="Permalink to &quot;面板介绍&quot;">​</a></h2><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_14.46.14.png" alt=""></p><p>可以看到整个界面还是比较简洁，整体包含：功能区、菜单栏、抓包记录、请求详情、抓包过滤等一些区域</p><h2 id="抓包记录" tabindex="-1">抓包记录 <a class="header-anchor" href="#抓包记录" aria-label="Permalink to &quot;抓包记录&quot;">​</a></h2><p>当正在抓包时左上角的<code>Record</code>会显示红色，此时whistle会将所有的请求抓取到中间面板列表</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_15.02.35.png" alt=""></p><p>底部可以通过关键字、正则过滤自己想要的数据</p><h2 id="规则" tabindex="-1">规则 <a class="header-anchor" href="#规则" aria-label="Permalink to &quot;规则&quot;">​</a></h2><p>规则主要来拦截不同的请求，根据设置的规则命中目标请求后，根据选择响应命令返回，其中包含：延时、替换等多种形式功能</p><p>下面是创建的一个名叫<code>App Test</code>的规则集，里面我们就使用了2个规则：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_15.12.56.png" alt=""></p><div class="language-sh line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki material-theme-palenight vp-code"><code><span class="line"><span style="color:#676E95;font-style:italic;"># 延时</span></span>
<span class="line"><span style="color:#FFCB6B;">/\\.(png</span><span style="color:#89DDFF;">|</span><span style="color:#FFCB6B;">jpg</span><span style="color:#89DDFF;">|</span><span style="color:#FFCB6B;">webp</span><span style="color:#89DDFF;">|</span><span style="color:#FFCB6B;">jpeg</span><span style="color:#BABED8;">)/ resDelay://2000</span></span>
<span class="line"></span>
<span class="line"><span style="color:#676E95;font-style:italic;"># 匹配到 usword.cn 结尾</span></span>
<span class="line"><span style="color:#82AAFF;">.</span><span style="color:#BABED8;">*usword.cn </span><span style="color:#C3E88D;">resBody://{test}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>什么意思呢？创建的每个规则都可以影响到请求，当规则后面打了✅就代表生效中；上方的<code>test</code>表示一个<code>规则值</code>，这个是用户创建的，下个章节我们讲</p><p><code>resDelay</code>、<code>resBody</code>都是一些常用的响应关键字，这里简单列举2个，更多查看文档</p><p>上面的规则只要匹配到这些结尾的图片，就会延时2s中响应，大家可以试试</p><h2 id="规则值" tabindex="-1">规则值 <a class="header-anchor" href="#规则值" aria-label="Permalink to &quot;规则值&quot;">​</a></h2><p>规则值主要就是提供给用户自定义响应内容的，用户可以创建多个规则值，然后在规则中使用规则值</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_15.38.11.png" alt=""></p><p>上面我们定义规则值 <code>test</code> 的响应内容为 <code>code: 200</code>，上面我们规则中拦截的是 <code>usword.cn</code> 的请求都返回<code>test</code>规则值，此时刷新网页：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_15.39.47.png" alt=""></p><h2 id="抓包详情面板" tabindex="-1">抓包详情面板 <a class="header-anchor" href="#抓包详情面板" aria-label="Permalink to &quot;抓包详情面板&quot;">​</a></h2><p>点击左侧任意一个抓包记录，右侧会显示详细的请求及响应内容，类似于Chrome Devtool面板那种</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_15.43.33.png" alt=""></p><p>可以看出上面部分为请求体，下面部分为响应体</p><h2 id="请求替换" tabindex="-1">请求替换 <a class="header-anchor" href="#请求替换" aria-label="Permalink to &quot;请求替换&quot;">​</a></h2><p>请求替换或者说代理是很多抓包工具常有的功能，在上面我们介绍了 <code>规则</code> 和 <code>规则值</code>后，大家应该也都知道怎么做了；主要是还有很多命令需要翻阅文档，这里就不再展开了</p><h2 id="https" tabindex="-1">HTTPS <a class="header-anchor" href="#https" aria-label="Permalink to &quot;HTTPS&quot;">​</a></h2><p>如果此时抓包HTTPS的请求，会发现响应体的内容都是乱码，也及时无法解密。至于为什么这里不做解释了，你可以查看我的往期文章<a href="https://blog.usword.cn/frontend/computer-network/http-protocol.html" target="_blank" rel="noreferrer">「HTTP协议及安全防范」</a>，关键就是由于没有证书，whistle没法成为目标服务器和本机系统的代理人，系统不会信任代理请求，因此需要将whistle内部的证书安装到系统中，这样whistle就可以拿着证书成为服务器和主机之间的代理人</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/005HV6Avgy1h7943v0e35j31520hsdu3.jpg" alt=""></p><p>安装系统证书非常简单，点击菜单栏<code>Install Root CA</code></p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_15.52.20.png" alt=""></p><p>此时重启whistle，重新抓包HTTPS请求，就可以看到解包后的内容了</p><h2 id="抓包手机请求" tabindex="-1">抓包手机请求 <a class="header-anchor" href="#抓包手机请求" aria-label="Permalink to &quot;抓包手机请求&quot;">​</a></h2><p>手机抓包已经成了很常用的功能，那么在whistle中操作也非常简单，也是点击菜单栏<code>Proxy Settings</code>：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_15.54.35.png" alt=""></p><p>自定义whistle端口，并设置为系统代理：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_15.54.54.png" alt=""></p><p>查看主机ip后，打开手机找到和主机同一WiFi，点击代理设置，将ip和端口输入后保存：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/IMG_0103.jpg" alt=""></p><p>此时访问网页，就可以抓到内容了</p><h2 id="手机配置https" tabindex="-1">手机配置HTTPS <a class="header-anchor" href="#手机配置https" aria-label="Permalink to &quot;手机配置HTTPS&quot;">​</a></h2><p>和主机HTTPS抓包道理一样，如果手机要能信任代理人，就必须在系统中植入whistle的证书；那么使用whistle可以很方便的安装证书到手机中</p><p>用户可以直接点击<code>Settings</code>就会弹出下载证书的二维码，这时候使用手机扫描访问就会自动下载：</p><p><img src="https://ihengshuai-demo1.oss-cn-beijing.aliyuncs.com/iShot_2024-12-23_16.02.15.png" alt=""></p><p>下载到手机后，需要在手机设置里点击证书，会弹出 <code>信任证书</code> 此时输入手机密码即可，这里不做演示了，可以查看往期其他的抓包软件演示</p><h2 id="插件" tabindex="-1">插件 <a class="header-anchor" href="#插件" aria-label="Permalink to &quot;插件&quot;">​</a></h2><p>插件系统是whistle核心特色之一。通过插件，Whistle 可以扩展功能以满足各种调试需求，例如接口录制、回放、远程调试、Mock 数据生成等。插件是基于 Node.js 开发的，可以根据项目需求自行编写或安装已有的插件</p><p>你可以前往官方文档查看了解插件系统，比较简单</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>除了文中提到的功能外，whistle还有很多实用的功能，你可以查看<a href="https://wproxy.org/whistle/" target="_blank" rel="noreferrer">whistle官方文档</a></p><p>whistle基于Node实现的跨平台web调试代理工具，类似的工具有Windows平台上的Fiddler，主要用于查看、修改HTTP、HTTPS、Websocket的请求、响应，也可以作为HTTP代理服务器使用，不同于Fiddler通过断点修改请求响应的方式，whistle采用的是类似配置系统hosts的方式，一切操作都可以通过配置实现，支持域名、路径、正则表达式、通配符、通配路径等多种匹配方式，且可以通过Node模块扩展功能</p>`,62)),a(o),a(l)])}const k=i(d,[["render",u]]);export{_ as __pageData,k as default};
